-- Product Test Data - 15000 records
-- For row storage and column storage performance comparison
-- Table structure: product_id, product_name, category, price, stock_quantity, supplier, created_date

-- 1. Create row storage table
CREATE TABLE demo_products_row (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100) NOT NULL,
    category VARCHAR(50),
    price DECIMAL(10,2),
    stock_quantity INT,
    supplier VARCHAR(50),
    created_date DATE
);

-- 2. Create column storage table
CREATE TABLE demo_products_column (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100) NOT NULL,
    category VARCHAR(50),
    price DECIMAL(10,2),
    stock_quantity INT,
    supplier VARCHAR(50),
    created_date DATE
);

-- 3. Insert 15000 product records
-- Row storage data















-- Copy data to column storage table

-- 4. Create indexes
CREATE INDEX idx_prod_row_category ON demo_products_row(category);
CREATE INDEX idx_prod_row_price ON demo_products_row(price);
CREATE INDEX idx_prod_row_supplier ON demo_products_row(supplier);

CREATE INDEX idx_prod_col_category ON demo_products_column(category);
CREATE INDEX idx_prod_col_price ON demo_products_column(price);
CREATE INDEX idx_prod_col_supplier ON demo_products_column(supplier);

-- 5. Performance test queries

-- Test 1: Full table scan performance
-- Row storage
SELECT COUNT(*) FROM demo_products_row;
SELECT AVG(price) FROM demo_products_row;
SELECT AVG(stock_quantity) FROM demo_products_row;

-- Column storage
SELECT COUNT(*) FROM demo_products_column;
SELECT AVG(price) FROM demo_products_column;
SELECT AVG(stock_quantity) FROM demo_products_column;

-- Test 2: Aggregation query performance (column storage advantage)
-- Row storage
SELECT category, COUNT(*), AVG(price), MAX(price), MIN(price), SUM(stock_quantity)
FROM demo_products_row GROUP BY category ORDER BY AVG(price) DESC;

-- Column storage
SELECT category, COUNT(*), AVG(price), MAX(price), MIN(price), SUM(stock_quantity)
FROM demo_products_column GROUP BY category ORDER BY AVG(price) DESC;

-- Test 3: Range query performance
-- Row storage
SELECT * FROM demo_products_row WHERE price BETWEEN 100 AND 500;
SELECT * FROM demo_products_row WHERE stock_quantity > 100 AND stock_quantity < 500;

-- Column storage
SELECT * FROM demo_products_column WHERE price BETWEEN 100 AND 500;
SELECT * FROM demo_products_column WHERE stock_quantity > 100 AND stock_quantity < 500;

-- Test 4: Single column query performance (column storage advantage)
-- Row storage
SELECT price FROM demo_products_row WHERE category = 'Electronics';
SELECT AVG(price) FROM demo_products_row WHERE category = 'Electronics';

-- Column storage
SELECT price FROM demo_products_column WHERE category = 'Electronics';
SELECT AVG(price) FROM demo_products_column WHERE category = 'Electronics';

-- Test 5: Complex analysis query
-- Row storage
SELECT category,
       CASE WHEN price < 50 THEN 'Low'
            WHEN price BETWEEN 50 AND 200 THEN 'Medium'
            ELSE 'High' END as price_range,
       COUNT(*) as count,
       AVG(stock_quantity) as avg_stock
FROM demo_products_row
GROUP BY category, price_range
ORDER BY category, price_range;

-- Column storage
SELECT category,
       CASE WHEN price < 50 THEN 'Low'
            WHEN price BETWEEN 50 AND 200 THEN 'Medium'
            ELSE 'High' END as price_range,
       COUNT(*) as count,
       AVG(stock_quantity) as avg_stock
FROM demo_products_column
GROUP BY category, price_range
ORDER BY category, price_range;

-- Test 6: Update operation performance (row storage advantage)
-- Row storage
UPDATE demo_products_row SET price = price * 1.1 WHERE category = 'Electronics';
UPDATE demo_products_row SET stock_quantity = stock_quantity - 10 WHERE stock_quantity > 100;

-- Column storage
UPDATE demo_products_column SET price = price * 1.1 WHERE category = 'Electronics';
UPDATE demo_products_column SET stock_quantity = stock_quantity - 10 WHERE stock_quantity > 100;

