-- 8. Performance statistics
-- View table size and row count
SELECT 'demo_products_row' as table_name, COUNT(*) as row_count FROM demo_products_row
UNION ALL
SELECT 'demo_products_column' as table_name, COUNT(*) as row_count FROM demo_products_column;

-- View data distribution
SELECT category, COUNT(*) as count, AVG(price) as avg_price, AVG(stock_quantity) as avg_stock
FROM demo_products_row GROUP BY category ORDER BY count DESC;
